84	                // 处置任务：(incident_id, task_key) 唯一
85	                st.execute("INSERT INTO incident_tasks (incident_id, task_key, group_code, title,"
86	                        + " status, created_by, created_at, updated_at) VALUES (1,'T-1','G','t',"
87	                        + "'OPEN','alice','" + Timestamp.from(now) + "','" + Timestamp.from(now)
88	                        + "')");
