91	                    st.execute("INSERT INTO incident_tasks (incident_id, task_key, group_code,"
92	                            + " title, status, created_by, created_at, updated_at) VALUES"
93	                            + " (1,'T-1','G','t2','OPEN','alice','" + Timestamp.from(now) + "','"
94	                            + Timestamp.from(now) + "')");
95	                } catch (Exception e) {
96	                    duplicateTaskRejected = true;
97	                }
