99	
100	                // 阻塞边：(task_id, blocker_incident_id) 唯一
101	                st.execute("INSERT INTO incident_task_blockers (task_id, blocker_incident_id,"
102	                        + " created_at) VALUES (1,1,'" + Timestamp.from(now) + "')");
103	                boolean duplicateBlockerRejected = false;
